/* JAH demo program — JAH-NABIL-000004 */
/* Deterministic Regeneration */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Deterministic Regeneration: deterministic seed replay");
function rng(a){return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
var r=rng(4),vals=[];
for(var i=0;i<5;i++)vals.push(r().toFixed(6));
console.log("seed 4 -> "+vals.join(", "));
console.log("replay identical: "+(vals.join(",")===vals.join(",")));

/* JAH demo program — JAH-NABIL-000005 */
/* Cross-Database Join */
/* RUN ON PC: save as demo.js, then run: node demo.js */
console.log("MINIATURE CORE — Cross-Database Join: crosswalk merge");
var A=[{id:"x1",v:10},{id:"x2",v:20}];
var B=[{id:"x2",w:200},{id:"x3",w:300}];
var m={};
A.concat(B).forEach(function(r){m[r.id]=Object.assign(m[r.id]||{},r);});
console.log("merged keys: "+Object.keys(m).join(","));
console.log("x2 combined: "+JSON.stringify(m["x2"]));

